<?php
$s = sale_get(req_int('id')); if (!$s) throw new UserError('فروش یافت نشد');
$doc = row("SELECT id, number FROM docs WHERE sale_id=? AND status<>'void' ORDER BY id DESC LIMIT 1", [$s['id']]);
$act = '<a class="btn sm" target="_blank" href="index.php?p=print_receipt&id=' . $s['id'] . '">رسید</a> ' . ($doc ? '<a class="btn sm" href="' . h(page_url('doc', ['id' => $doc['id']])) . '">فاکتورِ ' . h(fa_num($doc['number'])) . '</a>' : (can('docs.edit') ? ui_btn_api('صدورِ فاکتور', 'sale_doc', ['sale_id' => $s['id']], ['class' => 'sm', 'then' => 'go:index.php?p=doc&id={id}']) : ''));
if ($s['partner_mode'] === 'hold' && $s['fulfil'] === 'hold' && can('partner.manage')) $act .= ' ' . ui_btn_api('آزادسازی برای ارسال', 'phold_release', ['sale_id' => $s['id']], ['class' => 'sm']);
echo ui_card('فروشِ ' . fa_num($s['number']), '<dl class="kv"><dt>تاریخ</dt><dd>' . jdate($s['at'], true) . '</dd><dt>شعبه / صندوق</dt><dd>' . h(($s['bname'] ?? '') . ' / ' . ($s['cbname'] ?? '—')) . '</dd><dt>فروشنده</dt><dd>' . h($s['chname'] ? 'فروشنده: ' . $s['chname'] : $s['seller_name']) . '</dd>'
    . '<dt>مشتری</dt><dd>' . ($s['customer_id'] ? '<a href="' . h(page_url('customer', ['id' => $s['customer_id']])) . '">' . h($s['cname']) . '</a>' : 'گذری') . '</dd>' . ($s['partner_mode'] ? '<dt>نوعِ سفارشِ همکار</dt><dd>' . h(partner_modes()[$s['partner_mode']] ?? '') . '</dd>' : '')
    . '<dt>جمع</dt><dd>' . ui_money($s['total']) . ' (مالیات ' . ui_money($s['tax']) . ')</dd>' . (can('reports.profit') ? '<dt>بهای تمام‌شده</dt><dd>' . ui_money($s['cost']) . '</dd>' : '') . '</dl>', $act);
echo ui_card('اقلام', ui_table(['title' => 'شرح', 'qty' => ['تعداد', fn($r) => qty_show((int)$r['qty'], $r['unit_id'] ? (int)$r['unit_id'] : null)], 'price' => ['فی', 'money'], 'disc' => ['تخفیف', 'money'], 'tax' => ['مالیات', 'money'], 'net' => ['خالص', 'money'], 'returned_qty' => ['برگشتی', 'num'], 'units' => ['دانه‌ها', fn($r) => '<code>' . h(implode(' ', json_decode((string)$r['units'], true) ?: [])) . '</code>']], $s['items']));
echo payreq_sale_card($s);
$offs = rows("SELECT * FROM sale_offsets WHERE sale_id=?", [$s['id']]);
if ($offs) echo ui_card('تهاترِ کالا در این فروش', ui_table(['title' => 'کالا', 'qty' => ['تعداد', 'num'], 'value' => ['ارزش', 'money'], 'state' => ['وضعیت', fn($r) => ui_badge(offset_states()[$r['state']] ?? $r['state'])]], $offs));
if ($s['amend_of']) echo '<p class="muted">این فروش اصلاحِ فروشِ <a href="' . h(page_url('sale', ['id' => $s['amend_of']])) . '">' . h(fa_num((string)val("SELECT number FROM sales WHERE id=?", [$s['amend_of']]))) . '</a> است.</p>';
foreach (rows("SELECT id, number, total FROM sales WHERE amend_of=?", [$s['id']]) as $am) echo '<p class="muted">اصلاح شد ← فروشِ <a href="' . h(page_url('sale', ['id' => $am['id']])) . '">' . h(fa_num($am['number'])) . '</a> (' . fa_money($am['total']) . ')</p>';
[$aok, $amsg] = amend_gate($s);
if ($aok) {
    $h = '<p class="muted">' . h($amsg) . '. اقلامِ پس‌داده به انبار برمی‌گردند و اقلامِ تازه فروشِ پیوسته می‌شوند؛ فقط مابه‌التفاوت گرفته یا پس داده می‌شود.</p><form class="form" data-api="sale_amend" data-then="reload" data-confirm="اصلاح ثبت شود؟"><input type="hidden" name="sale_id" value="' . $s['id'] . '">'
        . '<table class="tbl"><tr><th>قلم</th><th>مانده</th><th>پس می‌دهد</th></tr>';
    foreach ($s['items'] as $i => $it) if ($it['qty'] - $it['returned_qty'] > 0) $h .= '<tr><td>' . h($it['title']) . '</td><td>' . fa_num((string)($it['qty'] - $it['returned_qty'])) . '</td><td><input type="hidden" name="remove[' . $i . '][sale_item_id]" value="' . $it['id'] . '"><input name="remove[' . $i . '][qty]" inputmode="numeric" style="width:60px" value="0"></td></tr>';
    $h .= '</table><h3>اقلامِ تازه</h3><div class="amadd"></div><p><input class="amq" placeholder="افزودنِ کالا (جست‌وجو یا اسکن)…"></p>'
        . '<div class="grid">' . ui_field('method', ['مابه‌التفاوت با', 'select', 1, ['cash' => 'نقد (شیفتِ باز)', 'card' => 'کارت‌خوان', 'transfer' => 'کارت‌به‌کارت', 'credit' => 'حسابِ نسیه', 'wallet' => 'کیف پول']]) . ui_field('reason', ['دلیل', 'text']) . '</div><div class="actions"><button class="btn primary">ثبتِ اصلاح</button></div></form>'
        . '<script>document.addEventListener("DOMContentLoaded",function(){var C=window.Cell,q=document.querySelector(".amq"),box=document.querySelector(".amadd"),n=0;if(!q)return;C.productPicker(q,function(p,v){var i=n++;var d=document.createElement("div");d.innerHTML=C.esc(p.name+(v?" — "+v.title:""))+\' × <input name="add[\'+i+\'][qty]" value="1" style="width:50px"><input type="hidden" name="add[\'+i+\'][product_id]" value="\'+p.id+\'"><input type="hidden" name="add[\'+i+\'][variant_id]" value="\'+(v?v.id:"")+\'"> <button type="button" class="btn sm" onclick="this.parentNode.remove()">×</button>\';box.appendChild(d);q.value="";});});</script>';
    echo ui_card('اصلاحِ فروش (جابه‌جایی)', $h);
}
if (can('ship.manage')) { $shs = ship_list(['sale_id' => $s['id']]); $ads = $s['customer_id'] ? array_column(array_map(fn($a) => ['id' => $a['id'], 't' => address_text($a)], addresses_of((int)$s['customer_id'])), 't', 'id') : [];
    echo ui_card('ارسال و پیک', ui_table(['carrier' => ['روش', fn($r) => h(ship_carriers()[$r['carrier']] ?? $r['carrier'])], 'tracking' => ['رهگیری', 'code'], 'cost' => ['هزینه', 'money'], 'status' => ['وضعیت', fn($r) => ui_badge(ship_statuses()[$r['status']] ?? $r['status'])], 'created_at' => ['زمان', 'datetime']], $shs, ['empty' => 'هنوز ارسالی ثبت نشده.'])
        . '<details' . ($shs ? '' : ' open') . '><summary>ثبتِ ارسال</summary>' . ui_form('ship_save', ['carrier' => ['شرکت/روش', 'select', 1, ship_carriers()], 'courier_id' => ['پیک', 'select', 0, ui_opts("SELECT id, name FROM couriers WHERE active=1")], 'tracking' => ['کدِ رهگیری', 'ltr'],
            'address_id' => ['نشانیِ مشتری', 'select', 0, $ads], 'address' => ['یا نشانیِ دیگر', 'text'], 'cost' => ['هزینه', 'money'], 'payer' => ['پرداخت‌کننده', 'select', 1, ship_payers()], 'paid_from' => ['هزینه از', 'select', 0, ['cash' => 'صندوق', 'bank' => 'بانک']], 'cod_amount' => ['دریافت در محل', 'money'], 'sms' => ['پیامکِ رهگیری', 'check']],
            ['sms' => 1], ['hidden' => ['sale_id' => $s['id']], 'submit' => 'ثبتِ ارسال']) . ($s['customer_id'] && !$ads ? '<p class="muted">مشتری نشانیِ ثبت‌شده ندارد: ' . ui_btn_api('لینکِ ثبتِ نشانی برایش بفرست', 'addr_link', ['customer_id' => $s['customer_id'], 'sms' => 1], ['class' => 'sm', 'then' => 'none']) . '</p>' : '') . '</details>'); }
echo ui_card('دریافت‌ها', ui_table(['method' => ['روش', fn($r) => h(pay_methods()[$r['method']] ?? $r['method'])], 'amount' => ['مبلغ', 'money'], 'at' => ['زمان', 'datetime'], 'ref' => 'مرجع'], $s['receipts']));
if ($s['returns']) echo ui_card('برگشت‌ها', ui_table(['id' => ['#', 'num'], 'd' => ['تاریخ', 'date'], 'reason' => 'دلیل', 'amount' => ['مبلغ', 'money'], 'tax' => ['مالیات', 'money'], 'refund_method' => ['بازپرداخت', fn($r) => h(pay_methods()[$r['refund_method']] ?? '')]], $s['returns']));
if (can('pos.return') && in_array($s['fulfil'], ['done', 'shipped'], true)) {
    $h = '<form class="form" data-api="sale_return" data-confirm="برگشت ثبت شود؟"><input type="hidden" name="sale_id" value="' . $s['id'] . '"><table class="tbl"><tr><th>قلم</th><th>قابلِ برگشت</th><th>تعدادِ برگشت</th></tr>';
    foreach ($s['items'] as $i => $it) $h .= '<tr><td>' . h($it['title']) . '</td><td>' . fa_num($it['qty'] - $it['returned_qty']) . '</td><td><input type="hidden" name="items[' . $i . '][sale_item_id]" value="' . $it['id'] . '"><input name="items[' . $i . '][qty]" value="0" style="width:70px"></td></tr>';
    $h .= '</table><div class="grid">' . ui_field('reason', ['دلیل', 'text', 1]) . ui_field('method', ['بازپرداخت', 'select', 1, ['cash' => 'نقد (از شیفتِ باز)', 'card' => 'کارت', 'transfer' => 'کارت‌به‌کارت', 'credit' => 'کم از نسیه', 'wallet' => 'به کیف پول']]) . '</div><div class="actions"><button class="btn primary">ثبتِ برگشت</button></div></form>';
    echo ui_card('مرجوعی (فروش پاک نمی‌شود؛ برگشت سندِ جداست)', $h);
}
$sm = sms_ref_log('sale', (int)$s['id']); if ($sm) echo ui_card('پیامک‌های این فروش', ui_table(['at' => ['زمان', 'datetime'], 'tpl_key' => 'قالب', 'ok' => ['نتیجه', fn($r) => $r['ok'] ? ui_badge('رفت', 'ok') : ui_badge('نرفت', 'err')], 'msg' => 'پیام'], $sm));
